SELECT

FROM herb_atlas a
LEFT JOIN herb_species s ON s.id = a.species_id AND s.is_deleted = 0

    a.is_deleted = 0

        AND a.species_id = #{query.speciesId}


        AND (
            a.atlas_no LIKE CONCAT('%', #{query.keyword}, '%')
            OR a.atlas_title LIKE CONCAT('%', #{query.keyword}, '%')
            OR a.identification_points LIKE CONCAT('%', #{query.keyword}, '%')
            OR s.herb_name LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND a.image_type = #{query.imageType}


        AND a.growth_stage = #{query.growthStage}


        AND a.status = #{query.status}


ORDER BY a.created_at DESC
LIMIT #{offset}, #{pageSize}

SELECT a.id, a.species_id, s.herb_name, a.atlas_no, a.image_url, a.atlas_title, a.image_type, a.growth_stage, a.medicinal_part, a.source_type, a.identification_points, a.status, a.created_at, a.updated_at, a.is_deleted FROM herb_atlas a LEFT JOIN herb_species s ON s.id = a.species_id AND s.is_deleted = 0 WHERE a.is_deleted = 0 AND a.status = 1
AND a.species_id = #{speciesId}
ORDER BY a.id ASC
